-- ----------------------------
-- Table structure for chat_session
-- ----------------------------
DROP TABLE IF EXISTS `chat_session`;
CREATE TABLE `chat_session`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `friend_id` bigint(20) NOT NULL COMMENT '好友ID',
  `last_msg_id` bigint(20) NULL DEFAULT NULL COMMENT '最后一条消息ID',
  `last_msg_time` datetime(0) NULL DEFAULT NULL COMMENT '最后消息时间',
  `unread_count` int(11) NULL DEFAULT 0 COMMENT '未读消息数',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_session`(`user_id`, `friend_id`) USING BTREE,
  INDEX `idx_user_time`(`user_id`, `last_msg_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会话表' ROW_FORMAT = Dynamic;

