-- ----------------------------
-- Table structure for enc_file_share
-- ----------------------------
DROP TABLE IF EXISTS `enc_file_share`;
CREATE TABLE `enc_file_share`  (
  `share_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '分享ID',
  `file_id` bigint(20) NOT NULL COMMENT '文件ID',
  `owner_id` bigint(20) NOT NULL COMMENT '分享者ID',
  `target_user_id` bigint(20) NOT NULL COMMENT '接收者ID',
  `sym_key_enc` blob NOT NULL COMMENT '用接收者公钥加密的AES密钥',
  `permissions` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'READ' COMMENT '权限: READ-只读',
  `share_from_chat` tinyint(4) NULL DEFAULT 0 COMMENT '是否从聊天分享: 0-否 1-是',
  `expire_time` datetime(0) NULL DEFAULT NULL COMMENT '过期时间',
  `status` tinyint(4) NULL DEFAULT 0 COMMENT '状态: 0-有效 1-已撤销 2-已过期',
  `create_time` datetime(0) NULL DEFAULT current_timestamp() COMMENT '创建时间',
  PRIMARY KEY (`share_id`) USING BTREE,
  INDEX `idx_target_user`(`target_user_id`, `status`) USING BTREE,
  INDEX `idx_owner`(`owner_id`, `status`) USING BTREE,
  INDEX `idx_file`(`file_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '文件分享表' ROW_FORMAT = Dynamic;

