-- ----------------------------
-- Table structure for enc_user_key
-- ----------------------------
DROP TABLE IF EXISTS `enc_user_key`;
CREATE TABLE `enc_user_key`  (
  `key_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '密钥ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `public_key` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'RSA公钥(PEM格式)',
  `private_key_enc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'RSA私钥(加密存储)',
  `key_size` int(4) NULL DEFAULT 2048 COMMENT '密钥长度(2048/4096)',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态(0正常 1停用)',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`key_id`) USING BTREE,
  UNIQUE INDEX `uk_user_id`(`user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户RSA密钥对表' ROW_FORMAT = Dynamic;

