-- ----------------------------
-- Table structure for sys_friend_request
-- ----------------------------
DROP TABLE IF EXISTS `sys_friend_request`;
CREATE TABLE `sys_friend_request`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `from_user_id` bigint(20) NOT NULL COMMENT '申请人ID',
  `to_user_id` bigint(20) NOT NULL COMMENT '被申请人ID',
  `message` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '请求添加您为好友' COMMENT '申请留言',
  `status` tinyint(4) NULL DEFAULT 0 COMMENT '状态: 0-待处理 1-同意 2-拒绝',
  `create_time` datetime(0) NULL DEFAULT current_timestamp() COMMENT '创建时间',
  `handle_time` datetime(0) NULL DEFAULT NULL COMMENT '处理时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_to_user`(`to_user_id`, `status`) USING BTREE,
  INDEX `idx_from_user`(`from_user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '好友申请表' ROW_FORMAT = Dynamic;

