-- ----------------------------
-- Table structure for sys_user_friend
-- ----------------------------
DROP TABLE IF EXISTS `sys_user_friend`;
CREATE TABLE `sys_user_friend`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `friend_id` bigint(20) NOT NULL COMMENT '好友ID',
  `status` tinyint(4) NULL DEFAULT 1 COMMENT '状态: 0-待确认 1-已添加 2-已删除',
  `create_time` datetime(0) NULL DEFAULT current_timestamp() COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_friend`(`user_id`, `friend_id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_friend_id`(`friend_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '好友关系表' ROW_FORMAT = Dynamic;

